<?php

namespace App\Modules\Procurement\Models;

use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use App\Support\Enums\ProcurementRequestStatus;

/**
 * An auto-generated reorder suggestion for a product that has fallen
 * below its reorder point. Generated by the system (or a user acting as
 * the "generator"), then reviewed/approved/dismissed by a manager, and
 * optionally converted into a PurchaseOrder.
 */
class ProcurementRequest extends Model
{
    use HasFactory;

    /**
     * The attributes that are mass assignable.
     */
    protected $fillable = [
        'product_id',
        'current_stock',
        'reorder_point',
        'suggested_quantity',
        'average_daily_usage',
        'lead_time_days',
        'safety_stock',
        'is_seasonal',
        'seasonal_factor',
        'priority',
        'status',
        'generated_by',
        'reviewed_by',
        'review_notes',
        'generated_at',
        'reviewed_at',
    ];

    /**
     * The attributes that should be cast.
     */
    protected $casts = [
        'status' => ProcurementRequestStatus::class,
        'current_stock' => 'integer',
        'reorder_point' => 'integer',
        'suggested_quantity' => 'integer',
        'average_daily_usage' => 'decimal:2',
        'lead_time_days' => 'integer',
        'safety_stock' => 'integer',
        'is_seasonal' => 'boolean',
        'seasonal_factor' => 'decimal:2',
        'generated_at' => 'datetime',
        'reviewed_at' => 'datetime',
    ];

    /*
    |--------------------------------------------------------------------------
    | Relationships
    |--------------------------------------------------------------------------
    */

    /**
     * Get the product this reorder suggestion is for.
     */
    public function product(): BelongsTo
    {
        return $this->belongsTo(\App\Modules\Inventory\Models\Product::class);
    }

    /**
     * Get the user (or system actor) that generated this suggestion.
     */
    public function generator(): BelongsTo
    {
        return $this->belongsTo(\App\Models\User::class, 'generated_by');
    }

    /**
     * Get the user who reviewed/approved/dismissed this suggestion.
     */
    public function reviewer(): BelongsTo
    {
        return $this->belongsTo(\App\Models\User::class, 'reviewed_by');
    }

    /*
    |--------------------------------------------------------------------------
    | Scopes
    |--------------------------------------------------------------------------
    */

    /**
     * Scope to get requests by status.
     */
    public function scopeByStatus($query, ProcurementRequestStatus $status)
    {
        return $query->where('status', $status);
    }

    /**
     * Scope to get newly generated (not yet reviewed) requests.
     */
    public function scopePending($query)
    {
        return $query->whereIn('status', [
            ProcurementRequestStatus::GENERATED,
            ProcurementRequestStatus::REVIEWED,
            ProcurementRequestStatus::APPROVED,
        ]);
    }

    /**
     * Scope to get approved requests.
     */
    public function scopeApproved($query)
    {
        return $query->where('status', ProcurementRequestStatus::APPROVED);
    }

    /**
     * Scope to get urgent requests (high/urgent priority).
     */
    public function scopeUrgent($query)
    {
        return $query->whereIn('priority', ['high', 'urgent']);
    }

    /**
     * Scope to get requests by product.
     */
    public function scopeByProduct($query, $productId)
    {
        return $query->where('product_id', $productId);
    }

    /**
     * Scope to get requests within date range.
     */
    public function scopeBetweenDates($query, $startDate, $endDate)
    {
        return $query->whereBetween('generated_at', [$startDate, $endDate]);
    }

    /*
    |--------------------------------------------------------------------------
    | Accessors & Mutators
    |--------------------------------------------------------------------------
    */

    /**
     * Get the estimated cost of fulfilling this suggestion, based on the
     * product's current unit price.
     */
    public function getEstimatedCostAttribute(): float
    {
        if (!$this->relationLoaded('product') && !$this->product) {
            return 0.0;
        }

        return $this->suggested_quantity * ($this->product->unit_price ?? 0);
    }

    /**
     * Check if request is overdue for review, based on priority.
     */
    public function getIsOverdueAttribute(): bool
    {
        if ($this->status !== ProcurementRequestStatus::GENERATED) {
            return false;
        }

        $maxDays = match($this->priority) {
            'urgent' => 1,
            'high' => 2,
            'medium' => 5,
            'low' => 10,
            default => 7,
        };

        return $this->generated_at->copy()->addDays($maxDays)->isPast();
    }

    /*
    |--------------------------------------------------------------------------
    | Status Management
    |--------------------------------------------------------------------------
    */

    /**
     * Check if the request can be approved.
     */
    public function canBeApproved(): bool
    {
        return in_array($this->status, [ProcurementRequestStatus::GENERATED, ProcurementRequestStatus::REVIEWED])
            && $this->product
            && $this->suggested_quantity > 0;
    }

    /**
     * Check if the request can be dismissed.
     */
    public function canBeDismissed(): bool
    {
        return in_array($this->status, [ProcurementRequestStatus::GENERATED, ProcurementRequestStatus::REVIEWED]);
    }

    /**
     * Approve the reorder suggestion.
     */
    public function approve(\App\Models\User $reviewer): bool
    {
        if (!$this->canBeApproved()) {
            return false;
        }

        $this->status = ProcurementRequestStatus::APPROVED;
        $this->reviewed_by = $reviewer->id;
        $this->reviewed_at = now();

        return $this->save();
    }

    /**
     * Dismiss the reorder suggestion.
     */
    public function dismiss(\App\Models\User $reviewer, ?string $reason = null): bool
    {
        if (!$this->canBeDismissed()) {
            return false;
        }

        $this->status = ProcurementRequestStatus::DISMISSED;
        $this->reviewed_by = $reviewer->id;
        $this->reviewed_at = now();

        if ($reason) {
            $this->review_notes = $reason;
        }

        return $this->save();
    }

    /**
     * Mark the suggestion as converted into a purchase order.
     */
    public function markConverted(): bool
    {
        $this->status = ProcurementRequestStatus::CONVERTED_TO_PO;
        return $this->save();
    }

    /*
    |--------------------------------------------------------------------------
    | Static Methods
    |--------------------------------------------------------------------------
    */

    /**
     * Get requests requiring immediate attention.
     */
    public static function getRequiringAttention(): \Illuminate\Database\Eloquent\Collection
    {
        return static::pending()
            ->with(['product'])
            ->get()
            ->filter(function ($request) {
                return in_array($request->priority, ['high', 'urgent']) || $request->is_overdue;
            });
    }

    /**
     * Generate reorder suggestions for products below reorder point.
     *
     * @param \App\Models\User|null $generator The user acting as the generator (null for system-generated).
     */
    public static function generateForLowStockProducts(?\App\Models\User $generator = null): \Illuminate\Database\Eloquent\Collection
    {
        $calculator = app(\App\Modules\Procurement\Services\ReorderPointCalculator::class);
        
        $lowStockProducts = \App\Modules\Inventory\Models\Product::lowStock()
            ->where('is_active', true)
            ->where('reorder_level', '>', 0)
            ->get();

        $requests = collect();

        foreach ($lowStockProducts as $product) {
            // Skip if there's already a pending suggestion for this product
            if (static::where('product_id', $product->id)->pending()->exists()) {
                continue;
            }

            // Use available_quantity for low-stock check
            $availableQuantity = $product->available_quantity ?? $product->quantity;
            
            // T21: Subtract quantity already on order (open POs) to avoid duplicate suggestions
            $onOrderQuantity = \App\Modules\Procurement\Models\PurchaseOrderItem::whereHas(
                'purchaseOrder',
                fn($q) => $q->whereIn('status', ['approved', 'sent', 'received'])
            )->where('product_id', $product->id)->sum('quantity');

            $effectiveAvailable = $availableQuantity + $onOrderQuantity;

            // If effective available (stock + on-order) already meets reorder level, skip
            if ($effectiveAvailable >= $product->reorder_level) {
                continue;
            }

            // Adjust available quantity used in downstream calculations
            $availableQuantity = $effectiveAvailable;
            
            try {
                // Get calculated reorder point and recommendations
                $recommendations = $calculator->getReorderPointRecommendations($product);
                $optimalReorderPoint = $recommendations['recommendations'][95]['reorder_point'] ?? $product->reorder_level;
                
                // Calculate suggested quantity using calculator logic
                $demandAnalysis = $calculator->analyzeDemand($product, 60); // 60 days for request generation
                $leadTimeAnalysis = $calculator->analyzeLeadTime($product);
                
                // Suggested quantity = enough to cover lead time + buffer
                $leadTimeDemand = $demandAnalysis['average_daily_demand'] * $leadTimeAnalysis['average_lead_time'];
                $suggestedQuantity = max(1, ceil($leadTimeDemand - $availableQuantity));
                
            } catch (\Exception $e) {
                // Fallback to simple calculation if calculator fails
                $optimalReorderPoint = $product->reorder_level;
                $suggestedQuantity = max(1, ($product->reorder_level * 2) - $availableQuantity);
            }

            // Determine priority based on available stock level  
            $priority = $availableQuantity <= 0 ? 'urgent' :
                       ($availableQuantity < $optimalReorderPoint * 0.5 ? 'high' : 'medium');

            $request = static::create([
                'product_id' => $product->id,
                'current_stock' => $availableQuantity,
                'reorder_point' => $optimalReorderPoint,
                'suggested_quantity' => $suggestedQuantity,
                'priority' => $priority,
                'status' => ProcurementRequestStatus::GENERATED,
                'generated_by' => $generator?->id,
                'generated_at' => now(),
            ]);

            $requests->push($request);
        }

        return $requests;
    }
}
